{{/* @dot github.com/donseba/go-webthings/modules/newsletter.ConfirmationView */}}
{{/* Sent to a new subscriber; only confirmed subscribers receive mailings. */}}
{{define "subject"}}{{tl localizer "Please confirm your subscription"}}{{end}}

{{define "text"}}
{{with .Name}}{{tl localizer "Hello %s," .}}

{{end -}}
{{tl localizer "Thank you for subscribing to our newsletter. Please confirm your e-mail address with the link below."}}

{{.URL}}

{{tl localizer "If you did not subscribe, you can ignore this message."}}
{{end}}

Types.Decl:
type ConfirmationView struct {
	Email string
	// Name is empty when the subscriber gave none.
	Name string
	// Title is the newsletter's title in the subscriber's language.
	Title string
	// URL confirms the subscription.
	URL string
}

type Contact struct {
	Email string
	Name  string
	// Locale is the language of their mailings; empty or not one of the
	// site's languages is the site's default language.
	Locale string
	// ConfirmedAt is when they agreed to receive the newsletter; zero is now.
	ConfirmedAt time.Time
}

type Counts struct {
	Pending      int
	Confirmed    int
	Unsubscribed int
}

type ImportResult struct {
	// Added are new subscribers.
	Added int
	// Confirmed were waiting for their confirmation and are confirmed now.
	Confirmed int
	// Existing were confirmed already and are unchanged.
	Existing int
	// Unsubscribed left the list before and were not added again.
	Unsubscribed int
	// Invalid are the addresses that are not valid, as given.
	Invalid []string
}

type ImportView struct {
	Title   string
	BackURL string
	Form    form.RenderModel
	Errors  form.FieldErrors
	Result  *ImportResult
	// Skipped counts rows of the file left out because their status is not
	// confirmed.
	Skipped int
}

type MailingRow struct {
	Subject  string
	URL      string
	Language string
	Sent     string
	// Sending is set while the messages go out; Recipients counts them so far.
	Sending    bool
	Recipients int
}

type MailingView struct {
	Title   string
	BackURL string
	// Form edits a draft; nil for sent mailings and without edit rights.
	Form   *form.RenderModel
	Errors form.FieldErrors
	// Preview is the rendered body, for saved mailings.
	Preview  template.HTML
	Subject  string
	Language string
	// Audience is the number of subscribers a draft would go to now.
	Audience int
	// URL is the mailing's page, which shows the progress while it is sent.
	URL string
	// Sent is when sending started; Finished when every message went out.
	Sent     string
	Finished string
	// Sending is set while the messages go out. Total is the audience when
	// sending started; Recipients and Failed count the messages so far.
	Sending    bool
	Total      int
	Recipients int
	Failed     int
	Send       *form.RenderModel
	Delete     *form.RenderModel
}

type MailingsView struct {
	Title   string
	BackURL string
	NewURL  string
	// TrashURL shows the deleted subscribers and mailings in the admin's trash.
	TrashURL string
	Rows     []MailingRow
}

type Provider interface {
	Subscribe(ctx context.Context, email, name, locale string) error
	Unsubscribe(ctx context.Context, email, name, locale string) error
}

type Service struct {
	// contains unexported fields
}

type SignupView struct {
	// Key is the instance key; results arrive as ?<key>=<result>.
	Key   string
	Title string
	Intro template.HTML
	// Action is the address the signup form posts to.
	Action string
	// Result is "check-mail", "confirmed", "unsubscribed", "invalid",
	// "throttled" or empty.
	Result string
	// Form is the signup form's model (SubscribeInput) for go-form's
	// template functions, such as {{form_open .Form}} and {{form_field
	// .Form "email" nil}}; it returns the visitor to the element with the
	// id Key.
	Form form.RenderModel
}

type SubscribeInput struct {
	Email  string `form:"input,email"  name:"email"  label:"E-mail address" required:"true" maxLength:"254" validate:"mail" autocomplete:"email" placeholder:"you@example.com"`
	Name   string `form:"input,text"   name:"name"   label:"Name"                           maxLength:"200"                 autocomplete:"name"                                line:"true"`
	Locale string `form:"input,hidden" name:"locale"                                        maxLength:"35"                                                                     line:"true"`
}

type SubscribersView struct {
	Title   string
	Filters admin.Tabs
	Rows    []SubscriberRow
	// ExportURL is empty without the right to export.
	ExportURL   string
	MailingsURL string
	TextsURL    string
	// TrashURL shows the deleted subscribers and mailings in the admin's trash.
	TrashURL string
	// ImportURL is set for editors who may add subscribers.
	ImportURL string
	Pager     admin.Pager
}

type Text struct {
	Title  string `db:"title"`
	Intro  string `db:"intro"`
	Footer string `db:"footer"`
}
